CREATE DATABASE IF NOT EXISTS konfigurator_pc
  CHARACTER SET utf8mb4 COLLATE utf8mb4_polish_ci;
USE konfigurator_pc;

CREATE TABLE IF NOT EXISTS plyty_glowne (
  id INT PRIMARY KEY,
  producent VARCHAR(30) NOT NULL,
  model VARCHAR(150) NOT NULL,
  socket VARCHAR(20) NOT NULL,
  chipset VARCHAR(80) NOT NULL,
  typ_pamieci VARCHAR(100) NOT NULL,
  format VARCHAR(20) NOT NULL,
  liczba_slotow_ram TINYINT NULL,
  maksymalna_pamiec_gb SMALLINT NULL,
  liczba_slotow_m2 TINYINT NULL,
  liczba_portow_sata TINYINT NULL,
  standard_pcie_gpu VARCHAR(30) NULL,
  lan VARCHAR(30) NULL,
  wifi VARCHAR(30) NULL,
  bluetooth VARCHAR(30) NULL,
  usb4_thunderbolt VARCHAR(50) NULL,
  rok_premiery SMALLINT NULL,
  segment_rynku VARCHAR(30) NOT NULL,
  uwagi TEXT NULL,
  UNIQUE KEY uq_producent_model (producent, model),
  INDEX idx_socket (socket),
  INDEX idx_chipset (chipset),
  INDEX idx_ram (typ_pamieci),
  INDEX idx_format (format)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_polish_ci;

